def find_maximal_rectangles(grid, H, W):
    rectangles = []
    visited = set()
    from collections import deque

    for r in range(H):
        for c in range(W):
            if (r, c) in visited:
                continue
            val = grid[r][c]
            seen = set()
            queue = deque([(r, c)])

            while queue:
                curr_r, curr_c = queue.popleft()
                if (curr_r, curr_c) in seen:
                    continue
                seen.add((curr_r, curr_c))
                visited.add((curr_r, curr_c))

                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = curr_r + dr, curr_c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if grid[nr][nc] == val and (nr, nc) not in seen:
                            queue.append((nr, nc))

            r1, r2 = min(seen, key=lambda x: x)[0], max(seen, key=lambda x: x)[0]
            c1, c2 = min(seen, key=lambda x: x)[1], max(seen, key=lambda x: x)[1]

            rectangles.append({
                'val': val,
                'rows': (r1, r2),
                'cols': (c1, c2),
                'height': r2 - r1 + 1,
