            r_t = r
            while r_t > 0:
                if not all(inp[r_t-1][cc] == val for cc in range(c, c_end+1)):
                    break
                r_t -= 1
            r_b = r
            while r_b < len(inp) - 1:
                if not all(inp[r_b+1][cc] == val for cc in range(c, c_end+1)):
                    break
                r_b += 1
            height = r_b - r_t + 1

            if width >= min_side and height >= min_side:
                key = (val, r_t, r_b, c, c_end)
                if key not in seen:
                    seen.add(key)
                    found.append({
                        'val': val,
                        'area': width * height,
                        'min_side': min(width, height),
