    # And only perfect rectangles in remaining rows get transformed

    # Let me keep this flexible - just remove bottom 4 rows first
    limited_rows = 20
    grid_lines = grid_list[:limited_rows]

    # Parse into 2D array
    grid_2d = []
    for line in grid_lines:
        values = line.split()
        grid_2d.append(values)

    h, w = len(grid_2d), len(grid_2d[0])

    # Step 2: Find all maximal perfect rectangles
    maximal_rects = []
    visited = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if visited[r][c] or grid_2d[r][c] == ' ':
                continue

            val = grid_2d[r][c]

            # Find maximal rectangle
            height = 1
            width = 1

            # Expand in both directions
            # Expand upward
            for rr in range(r - 1, -1, -1):
                if all(grid_2d[rr][cc] == val for cc in range(c, c + width)):
                    height += 1
                else:
                    break

            # Expand downward
            for rr in range(r + height, h):
                if all(grid_2d[rr][cc] == val for cc in range(c, c + width)):
                    height += 1
                else:
                    break

            # Expand left
            for cc in range(c - 1, -1, -1):
                if all(grid_2d[rr][cc] == val for rr in range(r, r + height)):
                    width += 1
                else:
                    break

            # Expand right
            for cc in range(c + width, w):
                if all(grid_2d[rr][cc] == val for rr in range(r, r + height)):
                    width += 1
                else:
                    break

            # It's maximal
            for rr in range(r, r + height):
                for cc in range(c, c + width):
                    visited[rr][cc] = True

            maximal_rects.append((r, c, height, width, val))

    # Step 3: Mark cells to change to 4
    change_set = set()
    for r, c, height, width, val in maximal_rects:
        for rr in range(r, r + height):
            for cc in range(c, c + width):
                change_set.add((rr, cc))

    # Step 4: Apply transformation
    new_grid_2d = []
    for r in range(h):
        new_row = []
        for c in range(w):
            if (r, c) in change_set:
                new_row.append('4')
            else:
                new_row.append(grid_2d[r][c])
        new_grid_2d.append(new_row)

    # Step 5: Convert back to string
    output_lines = []
    for r in range(h):
        output_lines.append(' '.join(new_grid_2d[r]))

    return '\n'.join(output_lines)

