# Fix the transform function
def transform_2d_to_16(grid_str):
    """Transform function based on ARC rule"""
    # Parse grid
    grid_lines = grid_str.split('\n')

    # Limit to top 20 rows
    limited_rows = 20
    if len(grid_lines) > limited_rows:
        grid_lines = grid_lines[:limited_rows]

    grid_2d = [line.split() for line in grid_lines]
    h, w = len(grid_2d), len(grid_2d[0])

    # Find all maximal perfect rectangles
    maximal_rects = []
    for r in range(h):
        for c in range(w):
            val = grid_2d[r][c]
            if val == ' ':
                continue

            # Expand in all directions
            rowspan = [r]  # Rows in rectangle
            colspan = [c]  # Cols in rectangle

            # Expand upward
            for rr in range(r - 1, -1, -1):
                if all(grid_2d[rr][cc] == val for cc in colspan):
                    rowspan.append(rr)
                else:
                    break

            # Expand downward
            for rr in range(r + 1, h):
                if all(grid_2d[rr][cc] == val for cc in colspan):
                    rowspan.append(rr)
                else:
                    break

            # Expand left
            for cc in range(c - 1, -1, -1):
                if all(grid_2d[rr][cc] == val for rr in rowspan):
                    colspan.append(cc)
                else:
                    break

            # Expand right
            for cc in range(c + 1, w):
                if all(grid_2d[rr][cc] == val for rr in rowspan):
                    colspan.append(cc)
                else:
                    break

            # Mark this rectangle
            rowspan = set(rowspan)
            colspan = set(colspan)
            for rr in rowspan:
                for cc in colspan:
                    grid_2d[rr][cc] = '#'  # Mark rented

            maximal_rects.append({
                'rows': list(rowspan),
                'cols': list(colspan),
                'count': len(rowspan) * len(colspan)
            })

    # Apply transformation - mark cells to change to 4
    marked = set()
    for rect in maximal_rects:
        rows = rect['rows'][::-1]  # Sort descending
        cols = sorted(rect['cols'])
        for r in rows:
            for c in cols:
                marked.add((r, c))

    # Create output
    output_lines = []
    for r in range(h):
        new_row = []
        for c in range(w):
            if (r, c) in marked:
                new_row.append('4')
            else:
                new_row.append(grid_2d[r][c])
        output_lines.append(' '.join(new_row))

    return '\n'.join(output_lines)

