    for r in range(h):
        for c in range(w):
            val = grid_2d[r][c]
            if val == ' ':
                continue

            # Check if this starts a 2x2+ rectangle
            if h - r < 2 or w - c < 2:
                continue

            # Find maximal rectangle
            rowspan = [r]
            colspan = [c]

            # Expand upward
            for rr in range(r - 1, -1, -1):
                if all(grid_2d[rr][cc] == val for cc in colspan):
                    rowspan.append(rr)
                else:
                    break

            # Expand downward
            for rr in range(r + 1, h):
                if all(grid_2d[rr][cc] == val for cc in colspan):
                    rowspan.append(rr)
                else:
                    break

            # Expand left
            for cc in range(c - 1, -1, -1):
                if all(grid_2d[rr][cc] == val for rr in rowspan):
                    colspan.append(cc)
                else:
                    break

            # Expand right
            for cc in range(c + 1, w):
                if all(grid_2d[rr][cc] == val for rr in rowspan):
                    colspan.append(cc)
                else:
                    break

            height = len(rowspan)
