def find_maximal_rectangles_unique(grid_str, limit_rows=20):
    """Find all unique maximal rectangles >= 2x2"""
    grid_lines = grid_str.split('\n')[:limit_rows]
    grid_2d = [line.split() for line in grid_lines]
    h, w = len(grid_2d), len(grid_2d[0])

    visited = [[False] * w for _ in range(h)]
    maximal_rects = []

    for r in range(h):
        for c in range(w):
            val = grid_2d[r][c]
            if val == ' ':
                continue
            if visited[r][c]:
                continue

            # Try to grow a rectangle from (r, c)
            rowspan = [r]
            colspan = [c]

            # Expand upward
            for rr in range(r - 1, -1, -1):
                if all(grid_2d[rr][cc] == val for cc in colspan):
                    rowspan.append(rr)
                else:
                    break

            # Expand downward
            for rr in range(r + 1, h):
                if all(grid_2d[rr][cc] == val for cc in colspan):
                    rowspan.append(rr)
                else:
                    break

            # Expand left
            for cc in range(c - 1, -1, -1):
                if all(grid_2d[rr][cc] == val for rr in rowspan):
                    colspan.append(cc)
                else:
                    break

            # Expand right
            for cc in range(c + 1, w):
                if all(grid_2d[rr][cc] == val for rr in rowspan):
                    colspan.append(cc)
                else:
                    break

            height = len(rowspan)
            width = len(colspan)

            # Only keep if >= 2x2
            if height >= 2 and width >= 2:
                # Mark all cells as visited
                for rr in rowspan:
                    for cc in colspan:
                        visited[rr][cc] = True

                # Check if we can extend further (maximal)
                can_extend = False

                # Can we extend upward?
                if r > 0:
                    if all(grid_2d[r-1][cc] == val for cc in colspan):
                        can_extend = True

                # Can we extend downward?
                if r + height < h:
                    if all(grid_2d[r + height][cc] == val for cc in colspan):
                        can_extend = True

                # Can we extend left?
                if c > 0:
                    if all(grid_2d[rr][c-1] == val for rr in rowspan):
                        can_extend = True

                # Can we extend right?
                if c + width < w:
                    if all(grid_2d[rr][c+width] == val for rr in rowspan):
                        can_extend = True

                # This is a maximal rectangle with area >= 4
                if not can_extend:
                    key = (r, c, height, width, val)
                    maximal_rects.append((key, rowspan, colspan))

    return maximal_rects

